import pytest
import cv2
import numpy as np
import os
from tempfile import NamedTemporaryFile
from objects import Image  # Replace with the actual import

# Example base64 image
data_url = (
    "data:image/png;base64,"
)

def test_load_image_from_file():
    # Create a temporary image file
    temp_file = NamedTemporaryFile(delete=False, suffix=".jpg")
    temp_file_name = temp_file.name
    temp_file.close()

    # Write a dummy black image to it
    dummy_image = np.zeros((10, 10, 3), dtype=np.uint8)
    cv2.imwrite(temp_file_name, dummy_image)

    image_obj = Image(path=temp_file_name)
    image = image_obj.load_image()

    os.unlink(temp_file_name)  # Clean up

    assert isinstance(image, np.ndarray)
    assert image.shape == (10, 10, 3)